DROP DATABASE IF EXISTS db_perpustakaan;
CREATE DATABASE db_perpustakaan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_perpustakaan;
CREATE TABLE anggota(id_anggota CHAR(4) PRIMARY KEY,nama VARCHAR(50) NOT NULL,alamat VARCHAR(100),tgl_daftar DATE NOT NULL) ENGINE=InnoDB;
CREATE TABLE buku(id_buku CHAR(4) PRIMARY KEY,judul VARCHAR(100) NOT NULL,pengarang VARCHAR(50) NOT NULL,penerbit VARCHAR(50),tahun_terbit INT,stok INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE peminjaman(id_pinjam INT AUTO_INCREMENT PRIMARY KEY,id_anggota CHAR(4) NOT NULL,id_buku CHAR(4) NOT NULL,tgl_pinjam DATE NOT NULL,tgl_kembali DATE,status ENUM('dipinjam','kembali') NOT NULL DEFAULT 'dipinjam',FOREIGN KEY(id_anggota) REFERENCES anggota(id_anggota),FOREIGN KEY(id_buku) REFERENCES buku(id_buku)) ENGINE=InnoDB;
